import sympy

def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def get_prime_factorization_and_unwanted(n):
    d_n = D(n)
    if d_n == 0:
        return "D(0)=4, Factorization: 2^2, Unwanted: None" # Special case n=0, D(0)=4
    try:
        factors = sympy.factorint(d_n)

        # Identify unwanted primes
        unwanted_primes = {p for p in factors if p != 2 and p != 5}

        factor_str = ", ".join([f"{p}^{e}" for p, e in factors.items()])

        return f"D({n})={d_n}, Factorization: {factor_str}, Unwanted Primes: {sorted(list(unwanted_primes))}"
    except Exception as e:
        return f"D({n})={d_n}, Error during factorization: {e}"

results = []
for n in range(21):
    results.append(get_prime_factorization_and_unwanted(n))

for result in results:
    print(result)

import math

def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def prime_factorization(num):
    factors = {}
    d = 2
    temp = num
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def check_divisibility(n):
    d_n = D(n)
    if d_n == 0: # Should not happen for n >= 0
        return False

    factors = prime_factorization(d_n)

    # Check for unwanted prime factors (p != 2 and p != 5)
    for p in factors:
        if p != 2 and p != 5:
            return False

    # Check exponent constraints
    exp2 = factors.get(2, 0)
    exp5 = factors.get(5, 0)

    required_exp2 = 2 * n + 2
    required_exp5 = n + 1

    if exp2 > required_exp2 or exp5 > required_exp5:
        return False

    return True

solutions = []
# Brute force search up to n=30
for n in range(31):
    if check_divisibility(n):
        solutions.append(n)

print(f"Solutions found up to n=30: {solutions}")

def check_k_smooth(k):
    # Check if k is 5-smooth (prime factors only 2 or 5)
    if k == 1:
        return True
    i = 2
    while i * i <= k:
        while k % i == 0:
            if i != 2 and i != 5:
                return False
            k //= i
        i += 1
    return k == 1 or k == 5

a1_values = [1, 2, 3, 4, 5, 6, 7] # Check up to a1=7 for quick assessment
solutions = []
for a1 in a1_values:
    # K = 2^(2*a1 - 1) - 2^a1 + 1
    k = (2**(2*a1 - 1)) - (2**a1) + 1
    if check_k_smooth(k):
        n = (2**a1) - 2
        solutions.append(n)
        print(f"a1={a1}: K={k}, 5-smooth. n={n}")
    else:
        print(f"a1={a1}: K={k}, NOT 5-smooth.")

